INSERT INTO roles (role_id, role_name, description) VALUES
  (1, 'Admin', 'System super-user responsible for user access, role permissions, master settings, and overall monitoring.'),
  (2, 'Manager', 'Supervises clients, suppliers, projects, quotations, purchase orders, shipments, inventory, finance, estimation, and reports.'),
  (3, 'Operations Officer', 'Daily operational user for client, supplier, project, quotation, purchase order, shipment, inventory, and location updates.'),
  (4, 'Accounts Officer', 'Finance-focused user for invoices, payments, due alerts, finance summaries, and import cost calculations.');
INSERT INTO permissions (permission_id, permission_code, description) VALUES
  (1, 'USER_MANAGE', 'Create, activate, deactivate, and manage system users.'),
  (2, 'ROLE_MANAGE', 'Assign roles and manage role permissions.'),
  (3, 'CLIENT_MANAGE', 'Create, update, delete, search, and view clients.'),
  (4, 'SUPPLIER_MANAGE', 'Create, update, delete, search, and view suppliers.'),
  (5, 'PROJECT_MANAGE', 'Create and maintain project/contract records.'),
  (6, 'QUOTATION_MANAGE', 'Create, submit, approve, reject, and revise quotations.'),
  (7, 'PO_MANAGE', 'Create, approve, and receive purchase orders.'),
  (8, 'SHIPMENT_MANAGE', 'Create and update import/export shipment tracking.'),
  (9, 'INVENTORY_MANAGE', 'Manage inventory items and stock movements.'),
  (10, 'INVOICE_MANAGE', 'Create and manage invoices.'),
  (11, 'PAYMENT_MANAGE', 'Record and review invoice payments.'),
  (12, 'IMPORT_COST_VIEW', 'Calculate and review import cost and profit/loss.'),
  (13, 'BOQ_MANAGE', 'Create draft BOQ and project cost estimations.'),
  (14, 'PRICE_MANAGE', 'Manage material/labour price data, recommendations, and alerts.'),
  (15, 'REPORT_VIEW', 'View management and finance reports.'),
  (16, 'EMAIL_LOG_VIEW', 'View notification delivery logs and failures.');
